def solve_a2():
    solutions = []
    for s in range(10, 504):
        num = s**3 - 503
        den = 3*s + 503
        if num % den == 0:
            p = num // den
            discriminant = s**2 - 4*p
            if discriminant >= 0:
                sqrt_d = int(discriminant**0.5)
                if sqrt_d**2 == discriminant:
                    if (s - sqrt_d) % 2 == 0:
                        b = (s - sqrt_d) // 2
                        c = (s + sqrt_d) // 2
                        if b > 0 and c > 0:
                            solutions.append((2, b, c))
    return solutions

print(solve_a2())

