import math

def check_solution(b, target_const):
    try:
        c_turn = math.sqrt(6036 * b / 81)
    except ValueError:
        c_turn = b

    MAX_C = 1000 

    for c in range(b, MAX_C + 1):
        P_c = 27 * (c**3) - (6036 * b) * c + target_const

        if P_c == 0:
            print(f"Solution found: (a=3, b={b}, c={c})")
            return [c]

        if c > c_turn and P_c > 0:
            return []

    return []

